fn copy(src: &Vec<i32>, s_start: usize, dest: &Vec<i32>, d_start: usize, len: usize) -> Vec<i32> {
    // Preconditions (as stated in the problem). These assertions make the assumptions explicit.
    assert!(s_start <= src.len());
    assert!(d_start <= dest.len());
    assert!(s_start + len <= src.len());
    assert!(d_start + len <= dest.len());

    let mut result = dest.clone();

    if len == 0 {
        return result;
    }

    // Replace dest[d_start .. d_start+len] with src[s_start .. s_start+len].
    result[d_start..d_start + len].copy_from_slice(&src[s_start..s_start + len]);

    result
}